// ESLint 9 reads flat config only. @react-native/eslint-config is still
// eslintrc-format *and* pulls in eslint-plugin-ft-flow, which crashes on
// ESLint 9 (`context.getAllComments is not a function`) — so this package lints
// with typescript-eslint directly instead. Formatting is prettier's job.
const js = require('@eslint/js')
const tseslint = require('@typescript-eslint/eslint-plugin')
const tsparser = require('@typescript-eslint/parser')

module.exports = [
  {
    ignores: [
      'node_modules/**',
      'lib/**',
      // Generated by nitrogen, and vendored, respectively.
      'nitrogen/**',
      'cpp/**',
    ],
  },
  js.configs.recommended,
  {
    // Build/tooling config files are CommonJS running in node.
    files: ['*.config.js', 'react-native.config.js'],
    languageOptions: {
      sourceType: 'commonjs',
      globals: { module: 'writable', require: 'readonly', __dirname: 'readonly' },
    },
  },
  {
    files: ['**/*.ts', '**/*.tsx'],
    languageOptions: {
      parser: tsparser,
      parserOptions: { ecmaFeatures: { jsx: true } },
    },
    plugins: { '@typescript-eslint': tseslint },
    rules: {
      ...tseslint.configs.recommended.rules,
      // The reconciler and compiler cross typed boundaries deliberately.
      '@typescript-eslint/no-explicit-any': 'off',
      '@typescript-eslint/no-require-imports': 'off',
      'no-undef': 'off',
    },
  },
]
